)

const (
	jsonFormat = "json"
	textFormat = "text"
)

var (
	//go:embed flipt.cue
	cueFile             []byte
	ErrValidationFailed = errors.New("validation failed")
)

// ValidateBytes takes a slice of bytes, and validates them against a cue definition.
func ValidateBytes(b []byte) error {
	cctx := cuecontext.New()

	return validate(b, cctx)
}

func validate(b []byte, cctx *cue.Context) error {
	v := cctx.CompileBytes(cueFile)

	f, err := yaml.Extract("", b)
	if err != nil {
		return err
	}

	yv := cctx.BuildFile(f, cue.Scope(v))
	yv = v.Unify(yv)

	return yv.Validate()
}

// Location contains information about where an error has occurred during cue
// validation.
type Location struct {
	File   string `json:"file,omitempty"`
	Line   int    `json:"line"`
	Column int    `json:"column"`
}

// Error is a collection of fields that represent positions in files where the user
// has made some kind of error.
type Error struct {
	Path     string   `json:"path"`
	Message  string   `json:"message"`
	Location Location `json:"location"`
}

// Result contains every error found while validating a YAML document.
type Result struct {
	Errors []Error `json:"errors"`
}

// FeaturesValidator validates YAML feature definitions against the embedded CUE schema.
type FeaturesValidator struct {
	cue *cue.Context
	v   cue.Value
}

// NewFeaturesValidator compiles the embedded schema for repeated validation.
func NewFeaturesValidator() (*FeaturesValidator, error) {
	cctx := cuecontext.New()
	v := cctx.CompileBytes(cueFile)
	if err := v.Err(); err != nil {
		return nil, fmt.Errorf("compile features schema: %w", err)
	}

	return &FeaturesValidator{cue: cctx, v: v}, nil
}

// Validate checks a YAML document and returns all validation errors.
// Invalid input returns a populated Result together with ErrValidationFailed.
func (validator *FeaturesValidator) Validate(file string, b []byte) (Result, error) {
	result := Result{Errors: make([]Error, 0)}

	f, err := yaml.Extract(file, b)
	if err != nil {
		result.Errors = append(result.Errors, Error{
			Message:  err.Error(),
			Location: yamlSyntaxLocation(file, err),
		})
		return result, ErrValidationFailed
	}

	yv := validator.cue.BuildFile(f, cue.Scope(validator.v))
	yv = validator.v.Unify(yv)
	if err := yv.Validate(); err != nil {
		result.Errors = validationErrors(file, b, err)
		return result, ErrValidationFailed
	}

	return result, nil
}

type sourceLocation struct {
	key   Location
	value Location
}

func pathKey(path []string) string {
	return strings.Join(path, "\x00")
}

// CUE's YAML conversion can shift columns, particularly for fields inside a
// sequence. Read the YAML node positions directly to report source coordinates.
func yamlSourceLocations(file string, b []byte) map[string]sourceLocation {
	locations := make(map[string]sourceLocation)
	var document yamlv3.Node
	if err := yamlv3.Unmarshal(b, &document); err != nil {
		return locations
	}

	var walk func(*yamlv3.Node, []string)
	walk = func(node *yamlv3.Node, path []string) {
		if node == nil {
			return
		}

		key := pathKey(path)
		current := locations[key]
		if current.value.Line == 0 {
			current.value = Location{File: file, Line: node.Line, Column: node.Column}
			locations[key] = current
		}

		switch node.Kind {
		case yamlv3.DocumentNode:
			for _, child := range node.Content {
				walk(child, path)
			}
		case yamlv3.MappingNode:
			for i := 0; i+1 < len(node.Content); i += 2 {
				label, value := node.Content[i], node.Content[i+1]
				childPath := append(append([]string(nil), path...), label.Value)
				locations[pathKey(childPath)] = sourceLocation{
					key:   Location{File: file, Line: label.Line, Column: label.Column},
					value: Location{File: file, Line: value.Line, Column: value.Column},
				}
				walk(value, childPath)
			}
		case yamlv3.SequenceNode:
			for i, child := range node.Content {
				childPath := append(append([]string(nil), path...), strconv.Itoa(i))
				locations[pathKey(childPath)] = sourceLocation{
					value: Location{File: file, Line: child.Line, Column: child.Column},
				}
				walk(child, childPath)
			}
		}
	}

	walk(&document, nil)
	return locations
}

func errorLocation(file string, path []string, unknownField bool, positions map[string]sourceLocation, err cueerror.Error) Location {
	for length := len(path); length >= 0; length-- {
		if source, ok := positions[pathKey(path[:length])]; ok {
			if length == len(path) && unknownField && source.key.Line > 0 {
				return source.key
			}
			if source.value.Line > 0 {
				return source.value
			}
		}
	}

	// This also handles source forms, such as YAML aliases, that do not have a
	// direct path in the YAML node tree.
	for _, pos := range err.InputPositions() {
		if pos.IsValid() && (file == "" || pos.Filename() == file) {
			return Location{File: file, Line: pos.Line(), Column: pos.Column()}
		}
	}
	return Location{File: file, Line: 1, Column: 1}
}

func validationErrors(file string, b []byte, err error) []Error {
	positions := yamlSourceLocations(file, b)
	result := make([]Error, 0)
	seen := make(map[string]struct{})

	for _, cueErr := range cueerror.Errors(err) {
		path := cueErr.Path()
		message := cueErr.Error()
		// CUE also emits a summary before the useful branch errors of an invalid
		// disjunction. Reporting both would repeat the same failure.
		if strings.Contains(message, "errors in empty disjunction:") {
			continue
		}

		unknownField := strings.HasSuffix(message, "field not allowed")
		if unknownField && len(path) > 0 {
			message = fmt.Sprintf("field %q not allowed", path[len(path)-1])
		}
		location := errorLocation(file, path, unknownField, positions, cueErr)
		entry := Error{Path: strings.Join(path, "."), Message: message, Location: location}
		identity := fmt.Sprintf("%s\x00%s\x00%d\x00%d", entry.Path, entry.Message, location.Line, location.Column)
		if _, ok := seen[identity]; ok {
			continue
		}
		seen[identity] = struct{}{}
		result = append(result, entry)
	}

	if len(result) == 0 {
		result = append(result, Error{Message: err.Error(), Location: Location{File: file, Line: 1, Column: 1}})
	}

	sort.SliceStable(result, func(i, j int) bool {
		if result[i].Location.Line != result[j].Location.Line {
			return result[i].Location.Line < result[j].Location.Line
		}
		if result[i].Location.Column != result[j].Location.Column {
			return result[i].Location.Column < result[j].Location.Column
		}
		return result[i].Path < result[j].Path
	})
	return result
}

func yamlSyntaxLocation(file string, err error) Location {
	location := Location{File: file, Line: 1, Column: 1}
	message := err.Error()
	if file != "" {
		message = strings.TrimPrefix(message, file+":")
	}
	if line, _, ok := strings.Cut(message, ":"); ok {
		if n, conversionErr := strconv.Atoi(line); conversionErr == nil {
			location.Line = n
		}
	}
	return location
}

func writeErrorDetails(format string, cerrs []Error, w io.Writer) error {
	var sb strings.Builder

	buildErrorMessage := func() {
		sb.WriteString("❌ Validation failure!\n\n")

		for i := 0; i < len(cerrs); i++ {
			errString := fmt.Sprintf(`
- Message: %s
  File   : %s
  Line   : %d
  Column : %d
`, cerrs[i].Message, cerrs[i].Location.File, cerrs[i].Location.Line, cerrs[i].Location.Column)

			sb.WriteString(errString)
		}
	}

	switch format {
	case jsonFormat:
		allErrors := struct {
			Errors []Error `json:"errors"`
		}{
			Errors: cerrs,
		}

		if err := json.NewEncoder(os.Stdout).Encode(allErrors); err != nil {
			fmt.Fprintln(w, "Internal error.")
			return err
		}

		return nil
	case textFormat:
		buildErrorMessage()
	default:
		sb.WriteString("Invalid format chosen, defaulting to \"text\" format...\n")
		buildErrorMessage()
	}

	fmt.Fprint(w, sb.String())

	return nil
}

