func errorLocation(file string, path []string, unknownField bool, positions map[string]sourceLocation, err cueerror.Error) Location {
	for length := len(path); length >= 0; length-- {
		if source, ok := positions[pathKey(path[:length])]; ok {
			if length == len(path) && unknownField && source.key.Line > 0 {
				return source.key
			}
			if source.value.Line > 0 {
				return source.value
			}
		}
	}

	// This also handles source forms, such as YAML aliases, that do not have a
	// direct path in the YAML node tree.
	for _, pos := range err.InputPositions() {
		if pos.IsValid() && (file == "" || pos.Filename() == file) {
			return Location{File: file, Line: pos.Line(), Column: pos.Column()}
		}
	}
	return Location{File: file, Line: 1, Column: 1}
}

func validationErrors(file string, b []byte, err error) []Error {
	positions := yamlSourceLocations(file, b)
	result := make([]Error, 0)
	seen := make(map[string]struct{})

	for _, cueErr := range cueerror.Errors(err) {
		path := cueErr.Path()
		format, args := cueErr.Msg()
		message := fmt.Sprintf(format, args...)
		// CUE also emits a summary before the useful branch errors of an invalid
		// disjunction. Reporting both would repeat the same failure.
		if strings.Contains(message, "errors in empty disjunction:") {
			continue
		}

		unknownField := message == "field not allowed"
		if unknownField && len(path) > 0 {
			message = fmt.Sprintf("field %q not allowed", path[len(path)-1])
		} else if len(path) > 0 {
			message = path[len(path)-1] + ": " + message
		}
		location := errorLocation(file, path, unknownField, positions, cueErr)
		entry := Error{Path: strings.Join(path, "."), Message: message, Location: location}
		identity := fmt.Sprintf("%s\x00%s\x00%d\x00%d", entry.Path, entry.Message, location.Line, location.Column)
		if _, ok := seen[identity]; ok {
			continue
		}
		seen[identity] = struct{}{}
		result = append(result, entry)
	}

	if len(result) == 0 {
		result = append(result, Error{Path: "$", Message: err.Error(), Location: Location{File: file, Line: 1, Column: 1}})
	}

	sort.SliceStable(result, func(i, j int) bool {
		if result[i].Location.Line != result[j].Location.Line {
			return result[i].Location.Line < result[j].Location.Line
		}
		if result[i].Location.Column != result[j].Location.Column {
			return result[i].Location.Column < result[j].Location.Column
		}
		return result[i].Path < result[j].Path
	})
	return result
}

func yamlSyntaxLocation(file string, err error) Location {
	location := Location{File: file, Line: 1, Column: 1}
	for _, cueErr := range cueerror.Errors(err) {
		positions := append(cueErr.InputPositions(), cueErr.Position())
		for _, pos := range positions {
			if pos.IsValid() && (file == "" || pos.Filename() == file) {
				return Location{File: file, Line: pos.Line(), Column: pos.Column()}
			}
		}
	}

	message := err.Error()
	if file != "" {
		message = strings.TrimPrefix(message, file+":")
	}
	if line, rest, ok := strings.Cut(message, ":"); ok {
		if n, conversionErr := strconv.Atoi(line); conversionErr == nil {
			location.Line = n
			if column, _, ok := strings.Cut(rest, ":"); ok {
				if n, conversionErr := strconv.Atoi(column); conversionErr == nil {
					location.Column = n
				}
			}
		}
	}
	return location
}

func writeErrorDetails(format string, cerrs []Error, w io.Writer) error {
	if format == jsonFormat {
		return json.NewEncoder(w).Encode(Result{Errors: cerrs})
	}
	if format != textFormat {
		if _, err := fmt.Fprintln(w, "Invalid format chosen, defaulting to \"text\" format..."); err != nil {
			return err
		}
	}
	if _, err := fmt.Fprintln(w, "❌ Validation failure!"); err != nil {
		return err
	}
	for _, validationErr := range cerrs {
		if _, err := fmt.Fprintf(w, "%s:%d:%d: %s: %s\n",
			validationErr.Location.File, validationErr.Location.Line,
			validationErr.Location.Column, validationErr.Path, validationErr.Message); err != nil {
			return err
		}
	}
	return nil
}

// ValidateFiles takes a slice of strings as filenames and validates them against
// our cue definition of features.
func ValidateFiles(dst io.Writer, files []string, format string) error {
	validator, err := NewFeaturesValidator()
	if err != nil {
		return err
	}

	cerrs := make([]Error, 0)
	for _, file := range files {
		b, readErr := os.ReadFile(file)
		if readErr != nil {
			cerrs = append(cerrs, Error{
				Path:     "$",
				Message:  fmt.Sprintf("failed to read file: %v", readErr),
				Location: Location{File: file},
			})
			continue
		}
		result, validationErr := validator.Validate(file, b)
		if validationErr != nil && !errors.Is(validationErr, ErrValidationFailed) {
			return validationErr
		}
		cerrs = append(cerrs, result.Errors...)
	}

	}

	if len(cerrs) > 0 {
		if err := writeErrorDetails(format, cerrs, dst); err != nil {
			return err
		}

		return ErrValidationFailed
	}

	if format == jsonFormat {
		return json.NewEncoder(dst).Encode(Result{Errors: cerrs})
	}

	if format != textFormat {
		if _, err := fmt.Fprintln(dst, "Invalid format chosen, defaulting to \"text\" format..."); err != nil {
			return err
		}
	}

	_, err = fmt.Fprintln(dst, "✅ Validation success!")
	return err
}

